<script setup lang="ts">
import { capturedResourcePath } from '../quick-capture.meta'; import type { CreatedResourceReference } from '../quick-capture.types'
const emit = defineEmits<{ dirty: [value: boolean]; pending: [value: boolean]; created: [value: CreatedResourceReference] }>(); const api = useApi(); const toast = useToast(); const state = reactive({ question: '', topic: '', difficulty: 'Medium' }); const pending = ref(false); const errors = ref<Record<string, string[]>>({}); const formError = ref('')
watch(state, () => emit('dirty', Boolean(state.question || state.topic)), { deep: true })
async function submit() { if (pending.value) return; if (!state.question.trim()) { errors.value = { question: ['Question is required.'] }; return } pending.value = true; emit('pending', true); try { const title = state.question.trim().slice(0, 200); const created = await api.post<{ id: string; title: string }>('/interview-questions', { title, question: state.question.trim(), topic: state.topic.trim() || 'General', difficulty: state.difficulty, notes: null }); toast.add({ title: 'Interview question created', color: 'success' }); emit('created', { id: created.id, title: created.title, targetPath: capturedResourcePath('InterviewQuestion', created.id) }) } catch (error) { const normalized = normalizeApiError(error); errors.value = normalized.fieldErrors; formError.value = normalized.detail ?? normalized.title } finally { pending.value = false; emit('pending', false) } }
</script>
<template><form class="grid gap-4" @submit.prevent="submit"><UFormField label="Question" required :error="errors.question?.[0]"><UTextarea v-model="state.question" autofocus :rows="6" class="w-full" /></UFormField><UFormField label="Topic" :error="errors.topic?.[0]"><UInput v-model="state.topic" class="w-full" placeholder="General" /></UFormField><UFormField label="Difficulty" :error="errors.difficulty?.[0]"><select v-model="state.difficulty" class="w-full rounded-md border border-default bg-default p-2"><option>Easy</option><option>Medium</option><option>Hard</option></select></UFormField><p v-if="formError" role="alert" class="text-sm text-error">{{ formError }}</p><UButton type="submit" label="Create question" block :loading="pending" :disabled="pending" /></form></template>
